#include <stdio.h>
#include <string.h>
#include "laststate/latch.h"
#define CHECK(x) do{if(!(x)){fprintf(stderr,"flash check failed: %s:%d\n",#x,__LINE__);return 1;}}while(0)
static uint8_t physical[8192],baseline[8192],workspace[1024],recovery_workspace[1024];
static ls_storage_backend_t raw_backend(ls_storage_sim_t *sim){ls_storage_backend_t raw={"nor-sim",sim,sizeof physical,1024,1,ls_storage_sim_read,ls_storage_sim_write,ls_storage_sim_erase,ls_storage_sim_sync};return raw;}
int main(void){memset(physical,0xff,sizeof physical);ls_storage_sim_t simulator={physical,sizeof physical,true,0,0,0};ls_storage_backend_t raw=raw_backend(&simulator);ls_flash_mirror_t mirror;CHECK(ls_flash_mirror_init(&mirror,&raw,workspace,sizeof workspace)==LS_OK);uint8_t old_value[32],new_value[32],readback[32];memset(old_value,0x11,sizeof old_value);memset(new_value,0x77,sizeof new_value);CHECK(mirror.backend.write(mirror.backend.context,100,old_value,sizeof old_value)==LS_OK);memcpy(baseline,physical,sizeof physical);for(uint32_t operation=1;operation<=6;operation++){memcpy(physical,baseline,sizeof physical);simulator=(ls_storage_sim_t){physical,sizeof physical,true,0,0,0};raw=raw_backend(&simulator);CHECK(ls_flash_mirror_init(&mirror,&raw,workspace,sizeof workspace)==LS_OK);ls_storage_sim_fail_at(&simulator,operation,8);(void)mirror.backend.write(mirror.backend.context,100,new_value,sizeof new_value);ls_storage_sim_reset_faults(&simulator);ls_flash_mirror_t recovered;CHECK(ls_flash_mirror_init(&recovered,&raw,recovery_workspace,sizeof recovery_workspace)==LS_OK);CHECK(recovered.backend.read(recovered.backend.context,100,readback,sizeof readback)==LS_OK);CHECK(!memcmp(readback,old_value,sizeof readback)||!memcmp(readback,new_value,sizeof readback));}return 0;}
